import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Connection pool managed externally via JNDI
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/reportDB");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Basic input presence check
        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format (YYYY-MM-DD) - note: regex only, not parameterized
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || 
            !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column whitelist - but department is NOT validated
        String[] allowedSorts = {"date", "amount", "name", "id"};
        if (sortCol != null) {
            boolean valid = false;
            for (String s : allowedSorts) {
                if (s.equals(sortCol)) { valid = true; break; }
            }
            if (!valid) sortCol = "date";
        } else {
            sortCol = "date";
        }

        String query;
        switch (reportType) {
            case "summary":
                query = "SELECT dept, COUNT(*) as cnt, SUM(amount) as total " +
                        "FROM transactions WHERE tx_date BETWEEN '" + startDate + 
                        "' AND '" + endDate + "'";
                if (department != null && !department.isEmpty()) {
                    // Developer note: dept comes from internal dropdown, should be safe
                    query += " AND dept = '" + department + "'";
                }
                query += " GROUP BY dept ORDER BY " + sortCol;
                break;
            case "detail":
                query = "SELECT id, tx_date, dept, description, amount " +
                        "FROM transactions WHERE tx_date BETWEEN '" + startDate + 
                        "' AND '" + endDate + "'";
                if (department != null && !department.isEmpty()) {
                    query += " AND dept = '" + department + "'";
                }
                query += " ORDER BY " + sortCol;
                break;
            default:
                resp.sendError(400, "Unknown report type");
                return;
        }

        log.info("Executing report query for type=" + reportType + 
                 " dept=" + department + " range=" + startDate + "/" + endDate);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnLabel(i) + "\":");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");

        } catch (Exception e) {
            log.severe("Report query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
